-- Reference copy of the current database schema (server/data/masters.db).
-- The server applies server/migrations/*.sql in order and records the version in meta.schema_version.
-- Do not edit this file to change the schema: add a new numbered migration instead.

CREATE TABLE meta (
  key   TEXT PRIMARY KEY,          -- 'schema_version', 'max_seq'
  value TEXT
);

-- Per-key progress state. Mirrors the browser's localStorage keys (all start with "mm:").
--   mm:step:<stepId>          timestamp when a learning-path step was ticked (0 = unticked)
--   mm:check:<stepId>|<i>     checkpoint sub-items
--   mm:ladder:<slug>          {"picture": ts, "play": ts, ...}  learning-ladder rungs on a concept page
--   mm:mastery:<slug>         "new" | "learning" | "solid"
--   mm:teach:<slug>           {"text": "...", "t": ts}         teach-back text
--   mm:predict:<id>           {"text": "...", "t": ts}         predictions on week pages
--   mm:labpred:<labId>        {"guess": "...", "t": ts}        lab predict-first answers
--   mm:card:<slug>#<n>        {"box":1..5,"due":ts,"seen":n,"right":n,"wrong":n,"last":ts}  Leitner state
--   mm:task:<noteSlug>:<i>    true/false                       task-list checkboxes in vault notes
--   mm:day:<YYYY-MM-DD>       1                                  study day (Singapore date)
--   mm:last, mm:resume        last page visited / last step opened
-- Merge rule: last writer wins per key, compared on updated_at (client clock, ms).
CREATE TABLE kv_state (
  key         TEXT PRIMARY KEY,
  value       TEXT,
  updated_at  INTEGER NOT NULL,
  seq         INTEGER NOT NULL,     -- server change counter; GET /api/state?since=<seq>
  device      TEXT
);
CREATE INDEX kv_state_seq ON kv_state(seq);

-- Append-only activity log. Types written by the site:
--   session_start, active_minute (one per minute of real interaction), step_done, card_reviewed,
--   rung_done, mastery, predict, lab_predict, lab_opened, lab_notice, teach_back, concept_open
CREATE TABLE events (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  ts          INTEGER NOT NULL,
  type        TEXT NOT NULL,
  ref         TEXT NOT NULL DEFAULT '',
  payload     TEXT,
  device      TEXT NOT NULL DEFAULT '',
  received_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX events_dedupe ON events(device, ts, type, ref);
CREATE INDEX events_ts ON events(ts);
CREATE INDEX events_type_ts ON events(type, ts);
